[
  {
    "text": "The REDMIX project aims to create a digital archive on mixed-ancestry people and groups in the Red Sea region from the 19th century to the present day.",
    "topic": "Digital Archive REDMIX"
  },
  {
    "text": "The paper discusses how the choice of digital tools for creating a participatory digital archive should be guided by the materiality of the sources.",
    "topic": "Digital Tool Materiality"
  },
  {
    "text": "Digital Humanities practices applied to heterogeneous historical and cultural contexts require methods that consider the public impact of the archive.",
    "topic": "Digital Humanities Methods"
  },
  {
    "text": "The integration of mixed-ancestry individuals into digital platforms can be a barrier for those without access to modern technologies or digital literacy.",
    "topic": "Digital Inclusion Barriers"
  },
  {
    "text": "The study highlights the role of digital archives and social media in negotiating and transmitting cultural memory within Tamil diasporic communities.",
    "topic": "Cultural Memory Transmission"
  }
]
